    private void confirmDownload(List<MediaItem> source,String title){List<MediaItem> items=new ArrayList<>(source);if(items.isEmpty()){a.toast("Выберите записи для скачивания");return;}CtpClient owner=a.s.ctp;if(!a.requireCard()||!a.requireStorage(()->confirmDownload(items,title)))return;a.showDeviceDialog(new AlertDialog.Builder(a).setTitle(title).setMessage("Файлов: "+items.size()+" · "+TransferService.bytes(ArchiveSelection.size(items))+"\n\nСохраняем оригиналы. Уже скачанные файлы будут пропущены, частичные — продолжены.").setNegativeButton("Отмена",null).setPositiveButton("Скачать",(d,w)->{if(a.deviceReady(owner,true))a.deviceAsync("Очередь скачивания",owner,true,c->TransferService.enqueueBatch(a,items),()->{a.toast("Записи добавлены в загрузки");a.startActivity(new Intent(a,DownloadsActivity.class));});}),true);}
