        a.fileList.setAdapter(a.new Rows(visible.size(),i->{MediaItem item=visible.get(i);return (item.locked()?"Защищено · ":"")+item.date()+"\n"+item.name+" · "+TransferService.bytes(item.size)+(!item.photo()?" · "+item.duration+" с":"");},i->activate(visible.get(i)),i->fileActions(visible.get(i)),i->MediaThumbnails.Source.remote(a.s,visible.get(i),owner)).selection(selecting,i->selected.contains(visible.get(i).path)).sections(i->i==0||!ArchiveSelection.day(visible.get(i)).equals(ArchiveSelection.day(visible.get(i-1)))?ArchiveSelection.day(visible.get(i)):""));
        a.fileList.setOnItemClickListener((parent,v,pos,id)->{int i=pos-a.fileList.getHeaderViewsCount();if(i>=0&&i<visible.size())activate(visible.get(i));});a.fileList.setOnItemLongClickListener((parent,v,pos,id)->{int i=pos-a.fileList.getHeaderViewsCount();if(i<0||i>=visible.size())return false;if(selecting)toggle(visible.get(i));else fileActions(visible.get(i));return true;});a.remoteEmptyPanel.setVisibility(visible.isEmpty()?View.VISIBLE:View.GONE);if(foundButton!=null){foundButton.setText(selecting?"Скачать выбранное · "+selected.size():"Скачать найденное · "+visible.size());foundButton.setEnabled(a.s.connected()&&a.s.cardPresent()&&!a.remoteLoading&&(!selecting?!visible.isEmpty():!selected.isEmpty()));}if(selectButton!=null)selectButton.setText(selecting?"Готово · "+selected.size():"Выбрать");if(filtersButton!=null)filtersButton.setText(a.filter!=0||from!=0?"Фильтры · включены":"Фильтры");renderRemoteState();
